 19515	    sf->var_buf = sf->arg_buf + arg_buf_len;
 19516	    sf->cur_sp = sf->var_buf + b->var_count;
 19517	    for(i = 0; i < argc; i++)
 19518	        sf->arg_buf[i] = JS_DupValue(ctx, argv[i]);
 19519	    n = arg_buf_len + b->var_count;
 19520	    for(i = argc; i < n; i++)
 19521	        sf->arg_buf[i] = JS_UNDEFINED;
