 19528	static void async_func_free_frame(JSRuntime *rt, JSAsyncFunctionState *s)
 19529	{
 19530	    JSStackFrame *sf = &s->frame;
 19531	    JSValue *sp;
 19532	
 19533	    if (sf->arg_buf) {
 19534	        /* cannot free the function if it is running */
 19535	        assert(sf->cur_sp != NULL);
 19536	        for(sp = sf->arg_buf; sp < sf->cur_sp; sp++) {
 19537	            JS_FreeValueRT(rt, *sp);
 19538	        }
 19539	        js_free_rt(rt, sf->arg_buf);
 19540	        sf->arg_buf = NULL;
