 19546	static JSValue async_func_resume(JSContext *ctx, JSAsyncFunctionState *s)
 19547	{
 19548	    JSRuntime *rt = ctx->rt;
 19549	    JSStackFrame *sf = &s->frame;
 19550	    JSValue func_obj, ret;
 19551	
 19552	    assert(!s->is_completed);
 19553	    if (js_check_stack_overflow(ctx->rt, 0)) {
 19554	        ret = JS_ThrowStackOverflow(ctx);
 19555	    } else {
 19556	        /* the tag does not matter provided it is not an object */
 19557	        func_obj = JS_MKPTR(JS_TAG_INT, s);
